let calendarCompetition='all',calendarScope='upcoming',calendarExpanded=false;
function calendarStatus(row){return row.status==='complete'?'결과 확정':row.status==='conditional'?'진출 시 예정':row.status==='scheduled'?'예정':row.phase==='full'?'경기 종료 · 결과 미확정':row.phase==='prep'?'바로 다음 경기':row.minute+'분 · '+(row.paused?'일시 정지':'진행 중');}
function renderSeasonCalendar(){
 if(view!=='cup')return;const host=$('season-calendar-panel');if(!host)return;const m=SeasonCalendar.read(season),esc=escapeText,rows=m.rows.filter(r=>(calendarCompetition==='all'||r.competition===calendarCompetition)&&(calendarScope==='all'||r.status!=='complete')),shown=calendarExpanded?rows:rows.slice(0,5),loadOpen=host.querySelector('details')?.open||false;
 host.innerHTML=`<section class="season-calendar-card" aria-labelledby="season-calendar-title"><div class="calendar-heading"><div><span class="eyebrow">남은 시즌 준비</span><h2 id="season-calendar-title" tabindex="-1">${m.year}시즌 통합 일정</h2></div><span>확정 ${m.completed}경기 · 남은 확정 대진 ${m.knownRemaining}경기</span></div><p class="calendar-intro">리그 사이의 국내컵·유럽 경기까지 순서대로 살펴보세요. ${m.conditional?'진출 여부가 미정인 '+m.conditional+'경기는 따로 표시합니다.':''}</p><div class="calendar-filters"><label>대회<select id="calendar-competition"><option value="all">전체 대회</option><option value="league">리그</option><option value="cup">국내컵</option><option value="europe">유럽 대회</option></select></label><label>범위<select id="calendar-scope"><option value="upcoming">남은 일정</option><option value="all">완료 경기 포함</option></select></label></div>${m.clusters.length?`<details class="calendar-load"${loadOpen?' open':''}><summary>선발을 나눠 쓸 시기 ${m.clusters.length}곳</summary><ul>${m.clusters.map(c=>`<li><strong>${c.round}R 전후</strong><span>${c.known?c.known+'경기 예정':''}${c.possible?(c.known?' + ':'')+'진출 시 '+c.possible+'경기 추가':''}</span></li>`).join('')}</ul><p>같은 라운드 전후에는 리그 → 국내컵 → 유럽 대회 순서로 진행합니다. 대회 경기 뒤 체력은 20 회복되며, 별도 주간 훈련은 없습니다.</p></details>`:''}<ol class="calendar-rows">${shown.map(r=>`<li class="calendar-row ${r.status}"${r.status==='current'?' aria-current="step"':''}><div class="calendar-date"><strong>${r.timing}</strong><small>${r.competition==='league'?'리그':r.competition==='cup'?'국내컵':'유럽'}</small></div><div class="calendar-match"><span>${esc(r.label)}${r.home===null?'':' · '+(r.home?'홈':'원정')}</span><strong>${r.opponent?esc(r.opponent.name):'대진 미정 · 진출 여부에 따라 결정'}</strong><small>${calendarStatus(r)}</small></div><div class="calendar-result">${r.score?`<strong>${r.score[0]} : ${r.score[1]}</strong>${r.penalties?`<small>승부차기 ${r.penalties[0]} : ${r.penalties[1]}</small>`:''}`:r.status==='conditional'?'<span>미정</span>':'<span>대</span>'}${r.detailsAvailable?'<button type="button" data-calendar-archive="'+esc(r.recordId)+'" class="secondary">경기 기록</button>':r.status==='current'?'<button type="button" id="calendar-open-match" class="secondary">'+(r.phase==='full'?'결과 확정하러 가기':'경기 준비·확인')+'</button>':''}</div></li>`).join('')}</ol>${rows.length>5?'<button type="button" id="calendar-expand" class="secondary" aria-expanded="'+calendarExpanded+'">'+(calendarExpanded?'가까운 5경기만 보기':'일정 '+(rows.length-5)+'경기 더 보기')+'</button>':''}${!rows.length?'<p class="calendar-empty">'+(m.complete?'이번 시즌 모든 경기를 마쳤습니다. 아래 시즌 결산에서 다음 시즌을 준비하세요.':'이 범위에 표시할 일정이 없습니다.')+'</p>':''}<p class="calendar-note">실제 날짜가 아닌 게임의 리그 라운드 기준입니다. 미확정 경기 결과와 다음 라운드 승자는 미리 계산하지 않습니다.</p><button type="button" id="calendar-squad" class="text-button">선수 체력과 선발 관리 →</button></section>`;
 const competition=$('calendar-competition'),scope=$('calendar-scope');competition.value=calendarCompetition;scope.value=calendarScope;
 competition.onchange=()=>{calendarCompetition=competition.value;calendarExpanded=false;renderSeasonCalendar();$('calendar-competition').focus({preventScroll:true});};scope.onchange=()=>{calendarScope=scope.value;calendarExpanded=false;renderSeasonCalendar();$('calendar-scope').focus({preventScroll:true});};
 const expand=$('calendar-expand');if(expand)expand.onclick=()=>{calendarExpanded=!calendarExpanded;renderSeasonCalendar();$('calendar-expand')?.focus({preventScroll:true});};
 host.querySelectorAll('[data-calendar-archive]').forEach(button=>button.onclick=()=>openMatchArchive(button.dataset.calendarArchive));
 const match=$('calendar-open-match');if(match)match.onclick=()=>setView('match');$('calendar-squad').onclick=()=>{squadTab='health';setView('squad');};
}
function openSeasonCalendar(){setView('cup');$('season-calendar-title')?.scrollIntoView({block:'start',behavior:'instant'});$('season-calendar-title')?.focus({preventScroll:true});}
